"""Load a JSON config file, falling back to built-in defaults."""

from __future__ import annotations

import json
import logging
from pathlib import Path
from typing import Any

log = logging.getLogger(__name__)

DEFAULTS: dict[str, Any] = {
    "host": "127.0.0.1",
    "port": 8080,
    "debug": False,
    "log_level": "INFO",
    "timeout": 30.0,
}


class ConfigError(Exception):
    """Raised when a config file exists but cannot be parsed."""


def _merge(base: dict[str, Any], override: dict[str, Any]) -> dict[str, Any]:
    """Recursively merge override into a copy of base."""
    merged = dict(base)
    for key, value in override.items():
        current = merged.get(key)
        if isinstance(current, dict) and isinstance(value, dict):
            merged[key] = _merge(current, value)
        else:
            merged[key] = value
    return merged


def load_config(
    path: str | Path,
    defaults: dict[str, Any] | None = None,
    *,
    strict: bool = True,
) -> dict[str, Any]:
    """Return config from `path` merged over `defaults`.

    A missing file yields the defaults unchanged. A malformed or
    non-object file raises ConfigError unless `strict` is False, in
    which case the defaults are used instead.
    """
    base = DEFAULTS if defaults is None else defaults
    path = Path(path)

    try:
        text = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        log.info("config %s not found; using defaults", path)
        return dict(base)
    except OSError as exc:
        if strict:
            raise ConfigError(f"cannot read {path}: {exc}") from exc
        log.warning("cannot read %s (%s); using defaults", path, exc)
        return dict(base)

    try:
        loaded = json.loads(text)
    except json.JSONDecodeError as exc:
        if strict:
            raise ConfigError(f"invalid JSON in {path}: {exc}") from exc
        log.warning("invalid JSON in %s (%s); using defaults", path, exc)
        return dict(base)

    if not isinstance(loaded, dict):
        if strict:
            raise ConfigError(f"{path} must contain a JSON object")
        log.warning("%s is not a JSON object; using defaults", path)
        return dict(base)

    return _merge(base, loaded)
